/* ============================================================================
   Data load - GDX_PSY_INSTRUMENT 'Borg CR10 Scale' and everything under it
   Generated by GDX_SKILL_RECORD_NEW_STUDY from intake.json.
   Prerequisite: psychometrics_model_firebird25.sql already applied.
   Safe to re-run: GDX_PSY_STUDY/GDX_PSY_PHENOMENON/GDX_PSY_CONSTRUCT rows are
   reused by name/title if they already exist; GDX_PSY_INSTRUMENT and
   everything under it are always inserted fresh (this is the new thing being
   registered) and will fail loudly on a genuine duplicate (NAME, VERSION)
   instead of silently reusing it.
   ============================================================================ */

/* study_type = 'PSYCHOMETRIC' -> default GDX_PSY_VARIABLE.VARIABLE_TYPE = 'PSYCHOLOGICAL'
   for every variable below, unless the intake set that variable's own
   variable_type explicitly (check the INSERT INTO GDX_PSY_VARIABLE lines). */

EXECUTE BLOCK AS
DECLARE VARIABLE V_ID_PHENOMENON BIGINT;
DECLARE VARIABLE V_ID_INSTRUMENT BIGINT;
DECLARE VARIABLE V_ID_ITEM BIGINT;
DECLARE VARIABLE V_ID_CONSTRUCT_1 BIGINT;
DECLARE VARIABLE V_ID_VARIABLE_1 BIGINT;
DECLARE VARIABLE V_ID_INDICATOR_1 BIGINT;
BEGIN
  SELECT ID_PHENOMENON FROM GDX_PSY_PHENOMENON WHERE NAME = 'Perceived Exertion' INTO :V_ID_PHENOMENON;
  IF (:V_ID_PHENOMENON IS NULL) THEN
  BEGIN
    INSERT INTO GDX_PSY_PHENOMENON (NAME, DESCRIPTION) VALUES ('Perceived Exertion', 'An individual''s subjective perception of how hard their body is working during physical exercise, integrating cues from the cardiovascular, respiratory, and musculoskeletal systems.')
      RETURNING ID_PHENOMENON INTO :V_ID_PHENOMENON;
  END

  SELECT ID_CONSTRUCT FROM GDX_PSY_CONSTRUCT WHERE NAME = 'Perceived Exertion (Borg CR10)' INTO :V_ID_CONSTRUCT_1;
  IF (:V_ID_CONSTRUCT_1 IS NULL) THEN
  BEGIN
    INSERT INTO GDX_PSY_CONSTRUCT (NAME, DOMAIN, DEFINITION) VALUES ('Perceived Exertion (Borg CR10)', 'PSYCHOMETRIC_NEW', 'The subjective intensity of effort, strain, discomfort and fatigue experienced during physical exercise, rated on Borg''s category-ratio scale with power-law (non-linear) numeric spacing.')
      RETURNING ID_CONSTRUCT INTO :V_ID_CONSTRUCT_1;
  END
  INSERT INTO GDX_PSY_PHENOMENON_CONSTRUCT (ID_PHENOMENON, ID_CONSTRUCT, RELATION_TYPE)
    SELECT :V_ID_PHENOMENON, :V_ID_CONSTRUCT_1, 'OPERATIONALIZES'
    FROM RDB$DATABASE
    WHERE NOT EXISTS (SELECT 1 FROM GDX_PSY_PHENOMENON_CONSTRUCT WHERE ID_PHENOMENON = :V_ID_PHENOMENON AND ID_CONSTRUCT = :V_ID_CONSTRUCT_1);

  INSERT INTO GDX_PSY_INSTRUMENT (NAME, VERSION, TYPE, DESCRIPTION, INSTRUCTIONS, ACTIVE)
    VALUES ('Borg CR10 Scale', '1982/1998', 'SINGLE_ITEM', 'Borg, G. (1982). A category scale with ratio properties for intermodal and interindividual comparisons. In H.-G. Geissler & P. Petzold (Eds.), Psychophysical judgment and the process of perception (pp. 25-34). Berlin: VEB Deutscher Verlag der Wissenschaften. Scale table: Borg, G. (1998). Borg''s Perceived Exertion and Pain Scales. Champaign, IL: Human Kinetics. Deliberately non-linear (ratio) spacing of numeric anchors: 0, 0.3, 0.5, 0.7, 1, 1.5, 2, 2.5, 3, 4, 5, 6, 7, 8, 9, 10, 11; the printed scale also carries an unbounded, un-numbered ''Absolute maximum / Highest possible'' mark above 11 for exceptionally supra-maximal ratings, not represented here as a fixed number.', 'Use this scale to rate how strenuous and tiring the exercise or effort feels to you right now. The numbers do not increase in equal steps: a small increase near the bottom of the scale represents a small change in effort, while the same numeric increase near the top represents a much larger change. It is your own feeling of exertion that matters -- do not underestimate it, but do not overestimate it either. Look at the scale and the descriptions, then choose the number (or a position between two numbers) that best matches how hard you are working right now. If your effort feels even harder than 10 (''Extremely strong / Maximal''), you may give an even higher rating.', 1)
    RETURNING ID_INSTRUMENT INTO :V_ID_INSTRUMENT;

  INSERT INTO GDX_PSY_INSTRUMENT_CONSTRUCT (ID_INSTRUMENT, ID_CONSTRUCT, WEIGHT) VALUES (:V_ID_INSTRUMENT, :V_ID_CONSTRUCT_1, 1);

  INSERT INTO GDX_PSY_VARIABLE (ID_CONSTRUCT, NAME, DESCRIPTION, OPERATIONAL_DEFINITION, VARIABLE_TYPE, MEASUREMENT_LEVEL)
    VALUES (:V_ID_CONSTRUCT_1, 'Perceived Exertion (Borg CR10)', 'Momentary self-reported intensity of physical exertion during exercise, rated on a ratio scale.', 'Single-item response to the Borg CR10 scale, from 0 (nothing at all) to 10 (extremely strong / maximal), with intermediate half-point anchors below 3 and whole-number anchors from 3 to 10; the scale is technically open-ended above 10 for rare supra-maximal ratings.', 'PSYCHOLOGICAL', 'RATIO')
    RETURNING ID_VARIABLE INTO :V_ID_VARIABLE_1;
  INSERT INTO GDX_PSY_INDICATOR (ID_VARIABLE, NAME, DESCRIPTION, INDICATOR_TYPE, MEASUREMENT_UNIT, DIRECTION, MIN_VALUE, MAX_VALUE)
    VALUES (:V_ID_VARIABLE_1, 'Perceived Exertion (Borg CR10) (score)', 'Raw score of the single Borg CR10 item, nominally 0 to 10 (the printed scale allows ratings above 10 in rare cases of supra-maximal effort, via an unbounded, un-numbered top mark).', 'SINGLE_ITEM_SCORE', 'SCALE_POINT', 'POSITIVE', 0, 10)
    RETURNING ID_INDICATOR INTO :V_ID_INDICATOR_1;

  INSERT INTO GDX_PSY_INSTRUMENT_ITEM (ID_INSTRUMENT, ITEM_ORDER, STATEMENT_TEXT, RESPONSE_TYPE, REQUIRED, WEIGHT)
    VALUES (:V_ID_INSTRUMENT, 1, 'How strenuous and tiring does the exercise feel to you right now?', 'CR10', 1, 1)
    RETURNING ID_ITEM INTO :V_ID_ITEM;
  INSERT INTO GDX_PSY_ITEM_ALTERNATIVE (ID_ITEM, ALTERNATIVE_ORDER, LABEL, NUMERIC_VALUE) VALUES (:V_ID_ITEM, 1, 'Nothing at all', 0);
  INSERT INTO GDX_PSY_ITEM_ALTERNATIVE (ID_ITEM, ALTERNATIVE_ORDER, LABEL, NUMERIC_VALUE) VALUES (:V_ID_ITEM, 2, '0.3', 0.3);
  INSERT INTO GDX_PSY_ITEM_ALTERNATIVE (ID_ITEM, ALTERNATIVE_ORDER, LABEL, NUMERIC_VALUE) VALUES (:V_ID_ITEM, 3, 'Extremely weak / Just noticeable', 0.5);
  INSERT INTO GDX_PSY_ITEM_ALTERNATIVE (ID_ITEM, ALTERNATIVE_ORDER, LABEL, NUMERIC_VALUE) VALUES (:V_ID_ITEM, 4, '0.7', 0.7);
  INSERT INTO GDX_PSY_ITEM_ALTERNATIVE (ID_ITEM, ALTERNATIVE_ORDER, LABEL, NUMERIC_VALUE) VALUES (:V_ID_ITEM, 5, 'Very weak', 1);
  INSERT INTO GDX_PSY_ITEM_ALTERNATIVE (ID_ITEM, ALTERNATIVE_ORDER, LABEL, NUMERIC_VALUE) VALUES (:V_ID_ITEM, 6, '1.5', 1.5);
  INSERT INTO GDX_PSY_ITEM_ALTERNATIVE (ID_ITEM, ALTERNATIVE_ORDER, LABEL, NUMERIC_VALUE) VALUES (:V_ID_ITEM, 7, 'Weak / Light', 2);
  INSERT INTO GDX_PSY_ITEM_ALTERNATIVE (ID_ITEM, ALTERNATIVE_ORDER, LABEL, NUMERIC_VALUE) VALUES (:V_ID_ITEM, 8, '2.5', 2.5);
  INSERT INTO GDX_PSY_ITEM_ALTERNATIVE (ID_ITEM, ALTERNATIVE_ORDER, LABEL, NUMERIC_VALUE) VALUES (:V_ID_ITEM, 9, 'Moderate', 3);
  INSERT INTO GDX_PSY_ITEM_ALTERNATIVE (ID_ITEM, ALTERNATIVE_ORDER, LABEL, NUMERIC_VALUE) VALUES (:V_ID_ITEM, 10, '4', 4);
  INSERT INTO GDX_PSY_ITEM_ALTERNATIVE (ID_ITEM, ALTERNATIVE_ORDER, LABEL, NUMERIC_VALUE) VALUES (:V_ID_ITEM, 11, 'Strong / Heavy', 5);
  INSERT INTO GDX_PSY_ITEM_ALTERNATIVE (ID_ITEM, ALTERNATIVE_ORDER, LABEL, NUMERIC_VALUE) VALUES (:V_ID_ITEM, 12, '6', 6);
  INSERT INTO GDX_PSY_ITEM_ALTERNATIVE (ID_ITEM, ALTERNATIVE_ORDER, LABEL, NUMERIC_VALUE) VALUES (:V_ID_ITEM, 13, 'Very strong', 7);
  INSERT INTO GDX_PSY_ITEM_ALTERNATIVE (ID_ITEM, ALTERNATIVE_ORDER, LABEL, NUMERIC_VALUE) VALUES (:V_ID_ITEM, 14, '8', 8);
  INSERT INTO GDX_PSY_ITEM_ALTERNATIVE (ID_ITEM, ALTERNATIVE_ORDER, LABEL, NUMERIC_VALUE) VALUES (:V_ID_ITEM, 15, '9', 9);
  INSERT INTO GDX_PSY_ITEM_ALTERNATIVE (ID_ITEM, ALTERNATIVE_ORDER, LABEL, NUMERIC_VALUE) VALUES (:V_ID_ITEM, 16, 'Extremely strong / Maximal', 10);
  INSERT INTO GDX_PSY_ITEM_ALTERNATIVE (ID_ITEM, ALTERNATIVE_ORDER, LABEL, NUMERIC_VALUE) VALUES (:V_ID_ITEM, 17, '11', 11);
  INSERT INTO GDX_PSY_INDICATOR_ITEM (ID_INDICATOR, ID_ITEM, WEIGHT, REVERSED) VALUES (:V_ID_INDICATOR_1, :V_ID_ITEM, 1, 0);
  -- item order: 1

END
